export function predictRow(values,model){let total=0;for(const tree of model.trees){let i=0;while(!Object.hasOwn(tree[i],'v')){const n=tree[i],v=values[n.f];let left;if(v===null||!Number.isFinite(v)||(n.c&&v<0)||(n.m==='Zero'&&v===0))left=n.d;else left=n.c?n.t.includes(v):v<=n.t;i=left?n.l:n.r;}total+=tree[i].v;}const z=total*model.std+model.mean;return model.target==='log1p'?Math.expm1(Math.max(0,Math.min(Math.log1p(1e7),z))):Math.max(0,Math.min(1e7,z));}
export function encodeFields(fields,model){return model.features.map(k=>{if(Object.hasOwn(model.schema,k)){const v=String(fields[k]??'').toLowerCase().trim();return model.schema[k].indexOf(v);}const v=fields[k];return v===''||v===null||v===undefined?null:Number(v);});}
